/**
 * Owns Knight state data and access to its existing private-state slot.
 * Inputs are the role component and native state; outputs retain the exact stored object, including assignment-before-return behavior.
 * The feature commit owns the single duel-consumption command; callers see a readonly
 * view of that same object. Lifecycle validation, player projection and checkpoint
 * encoding retain their current responsibilities. There is no mirror state or lease
 * check here, and failed later event publication does not refund this resource.
 * Pure payload/read data structures belong to the neutral role-state data owner;
 * this leaf retains original live references and concrete installation/commit operations.
 */
import type { KnightState, KnightReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";

export function setKnightState(roleComp: RoleComponent, state: KnightState): KnightReadState {
  (roleComp.privateState as { knight: KnightState })["knight"] = state;
  return state;
}

export function getKnightState(roleComp: RoleComponent): KnightReadState | undefined {
  return (roleComp.privateState as { readonly knight?: unknown })["knight"] as
    KnightReadState | undefined;
}

/** The caller has completed the original duel preflight; no second state read or check. */
export function consumeKnightDuel(state: KnightReadState): void {
  (state as { canDuel: boolean }).canDuel = false;
}

/**
 * 负责 骑士 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Role, Camp, Phase, KnightDuelWindow } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { getKnightState, setKnightState } from "./state";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";

export const KNIGHT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Knight,
    camp: Camp.Good,
    goodSide: "god",
    label: roleName("knight"),
    skillBrief: text("zh-CN", "role.knight.brief"),
  },
  runtime: {
    init: (role) => {
      setKnightState(role, { canDuel: true });
    },
    configuration: {
      schema: z.strictObject({
        enabledWindows: z
          .array(z.enum(KnightDuelWindow))
          .refine((windows) => new Set(windows).size === windows.length)
          .default([KnightDuelWindow.AfterSpeeches]),
      }),
      defaults: { enabledWindows: [KnightDuelWindow.AfterSpeeches] },
      apply: (config, value) => ({
        ...config,
        knight: value as {
          enabledWindows: KnightDuelWindow[];
        },
      }),
      serialize: (config) => ({
        enabledWindows: [...(config.knight?.enabledWindows ?? [KnightDuelWindow.AfterSpeeches])],
      }),
    },
    toolSpecs: [
      {
        name: "duel",
        parameters: {
          type: "object",
          properties: { target_id: { type: "number" }, confirm: { type: "boolean" } },
          required: ["target_id", "confirm"],
          additionalProperties: false,
        },
        argHint: 'duel args: {"target_id":number,"confirm":true}',
        userPromptHintKey: "action.knight.hint",
      },
    ],
    validationRules: {
      duel: ({ world, actorId, role, toolCall, phase, duelWindow, allowKnightDuel }) => {
        if (role.role !== Role.Knight || getKnightState(role)?.canDuel !== true)
          return { code: RuleError.KnightDuelUnavailable };
        if (
          phase !== Phase.Day ||
          !allowKnightDuel ||
          duelWindow === undefined ||
          !Object.values(KnightDuelWindow).includes(duelWindow)
        )
          return { code: RuleError.KnightDuelWindow };
        if (toolCall.name !== "duel" || toolCall.args.confirm !== true)
          return { code: RuleError.KnightDuelConfirm };
        if (toolCall.args.target_id === actorId || !isAliveTarget(world, toolCall.args.target_id))
          return { code: RuleError.KnightDuelTarget };
        return null;
      },
    },
    stageDirectives: [
      {
        match: (tools) => tools.length === 1 && tools[0] === "duel",
        messageKey: "action.knight.directive",
        text: text("zh-CN", "action.knight.directive"),
      },
    ],
    llmRepair: {
      coerce: {
        duel: (args) => {
          const target = numberOrNull(args.target_id);
          return target === null ? null : { target_id: target, confirm: Boolean(args.confirm) };
        },
      },
    },
    baselineAction: () => null,
  },
  presentation: nativeRolePresentation("knight"),
};

/**
 * 提供骑士决斗窗口与原生库存读取的具名公开入口。输入保留原 World、配置、角色、请求端口及回调，
 * 输出为原窗口类绑定和同一库存对象的只读类型视图；不复制资源或把类型当成运行权限屏障。
 * 窗口在原白天检查时点执行，等待之后与提交之前复验身体、生命版本和库存；具体提交拥有消耗，经理拥有死亡与阶段推进。
 * 读取、请求或提交失败保留原异常及已写前缀；公开入口不新增租约、镜像或自动清理。
 * 提交命令直接绑定本族实现，消耗先于公共事实和死亡提案；真实标死与日裁决仍归经理。
 */
export { getKnightState } from "./state";
export { KnightDuelWindow } from "./duel-window";

export { commitKnightDuel } from "./commit";

/**
 * Owns Idiot state data and access to its existing private-state slot.
 * Inputs are the role component and native state; outputs retain the exact stored object, including assignment-before-return behavior.
 * Existing mutation commands, lifecycle validation, player projection and checkpoint
 * encoding keep their current responsibilities. This leaf creates no mirror state,
 * consumes no resource and does not decide whether a request is authorized.
 * Pure payload/read data structures belong to the neutral role-state data owner;
 * this leaf retains original live references and concrete installation/commit operations.
 */
import type { IdiotState, IdiotReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";

export function setIdiotState(roleComp: RoleComponent, state: IdiotState): IdiotReadState {
  (roleComp.privateState as { idiot: IdiotState })["idiot"] = state;
  return state;
}

export function getIdiotState(roleComp: RoleComponent): IdiotReadState | undefined {
  return (roleComp.privateState as { readonly idiot?: unknown })["idiot"] as
    IdiotReadState | undefined;
}

/**
 * 负责 白痴 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { roleName, text } from "@ai-werewolf-arena/game-text";
/** 文件说明：白痴角色 profile。 */
import { Camp, Role } from "../../../../core/domain/model";
import { NativeRoleContributions } from "../contracts";
import { getIdiotState, setIdiotState } from "./state";
import { idiotVotedOutHook } from "../../../../rulesets/idiot-exile-outcome";

/** 白痴角色配置。 */
export const IDIOT_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Idiot,
    camp: Camp.Good,
    label: roleName("idiot"),
    skillBrief: text("zh-CN", "role.idiot.brief"),
    goodSide: "god",
  },
  runtime: {
    participation: (role) => {
      const enabled = getIdiotState(role)?.revealed !== true;
      return { canVote: enabled, canBeExiled: enabled, canBeSheriff: enabled };
    },
    init: (roleComp) => {
      setIdiotState(roleComp, { revealed: false });
    },
    votedOutHook: idiotVotedOutHook,
  },
  presentation: nativeRolePresentation("idiot"),
};

/**
 * 提供白痴状态读取与既有初始化命令的公开入口。输入是调用方原角色对象和安装数据；
 * 输出保留原只读状态引用及初始化写契约。每次读取或安装之前，权限检查与失败、关闭窗口
 * 仍由原调用方和状态所有者负责。本入口仅具名导出本角色状态函数，不校验、复制、冻结或存储状态。
 */
export { getIdiotState, setIdiotState } from "./state";

/**
 * Owns WhiteWolfKing state data and access to its existing private-state slot.
 * Inputs are the role component and native state; outputs retain the exact stored object, including assignment-before-return behavior.
 * Only the selected blast commit calls the concrete detonation-consumption command.
 * Readers keep a readonly view of that same object. Lifecycle validation, player
 * projection and checkpoint encoding retain their existing responsibilities;
 * consumption neither rechecks a lease nor refunds stock after publication fails.
 * Pure payload/read data structures belong to the neutral role-state data owner;
 * this leaf retains original live references and concrete installation/commit operations.
 */
import type { WhiteWolfKingState, WhiteWolfKingReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";

export function setWhiteWolfKingState(
  roleComp: RoleComponent,
  state: WhiteWolfKingState,
): WhiteWolfKingReadState {
  (roleComp.privateState as { white_wolf_king: WhiteWolfKingState })["white_wolf_king"] = state;
  return state;
}

export function getWhiteWolfKingState(roleComp: RoleComponent): WhiteWolfKingReadState | undefined {
  return (roleComp.privateState as { readonly white_wolf_king?: unknown })["white_wolf_king"] as
    WhiteWolfKingReadState | undefined;
}

/** Caller retains original blast validation, death proposals and publication order. */
export function consumeWhiteWolfDetonation(state: WhiteWolfKingReadState): void {
  (state as { canDetonate: boolean }).canDetonate = false;
}

/**
 * 负责 白狼王 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { text, roleName } from "@ai-werewolf-arena/game-text";
import { Role, ActionWindow, Phase } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { ORDINARY_WOLF_CONTRIBUTIONS } from "../wolf/ability-ports";
import { getWhiteWolfKingState, setWhiteWolfKingState } from "./state";
import { isAliveTarget } from "../../validation/contracts";
import { numberOrNull } from "../../llm/helpers";

export const WHITE_WOLF_KING_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.metadata,
    role: Role.WhiteWolfKing,
    label: roleName("white_wolf_king"),
    skillBrief: text("zh-CN", "role.white_wolf_king.brief"),
  },
  runtime: {
    ...ORDINARY_WOLF_CONTRIBUTIONS.runtime,
    canSelfDestruct: false,
    init: (role) => {
      setWhiteWolfKingState(role, { canDetonate: true });
    },
    toolSpecs: [
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.toolSpecs!.filter((spec) => spec.name !== "self_destruct"),
      {
        name: "self_destruct_with_target",
        parameters: {
          type: "object",
          properties: {
            reason: { type: "string" },
            confirm: { type: "boolean" },
            target_id: { type: ["number", "null"] },
          },
          required: ["reason", "confirm", "target_id"],
          additionalProperties: false,
        },
        argHint:
          'self_destruct_with_target args: {"reason":"...","confirm":true,"target_id":number|null}',
        userPromptHintKey: "action.white_wolf_king.hint",
      },
    ],
    validationRules: {
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.validationRules,
      self_destruct_with_target: ({
        world,
        actorId,
        role,
        toolCall,
        phase,
        actionWindow,
        allowSelfDestruct,
      }) => {
        if (role.role !== Role.WhiteWolfKing || getWhiteWolfKingState(role)?.canDetonate !== true)
          return { code: RuleError.WhiteWolfBlastUnavailable };
        if (phase !== Phase.Day && phase !== Phase.Voting) return { code: RuleError.BlastPhase };
        if (actionWindow === undefined || !Object.values(ActionWindow).includes(actionWindow))
          return { code: RuleError.BlastWindow };
        if (phase !== (actionWindow === ActionWindow.OnPreVote ? Phase.Voting : Phase.Day))
          return { code: RuleError.BlastPhase };
        if (!allowSelfDestruct) return { code: RuleError.BlastDisabled };
        if (toolCall.name !== "self_destruct_with_target" || toolCall.args.confirm !== true)
          return { code: RuleError.BlastConfirm };
        if (
          toolCall.args.target_id !== null &&
          (!isAliveTarget(world, toolCall.args.target_id) || toolCall.args.target_id === actorId)
        )
          return { code: RuleError.WhiteWolfBlastTarget };
        return null;
      },
    },
    stageDirectives: [
      ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.stageDirectives!,
      {
        match: (tools) => tools.length === 1 && tools[0] === "self_destruct_with_target",
        messageKey: "action.white_wolf_king.directive",
        text: text("zh-CN", "action.white_wolf_king.directive"),
      },
    ],
    llmRepair: {
      coerce: {
        ...ORDINARY_WOLF_CONTRIBUTIONS.runtime.llmRepair?.coerce,
        self_destruct_with_target: (args) => {
          const target = args.target_id === null ? null : numberOrNull(args.target_id);
          return args.target_id !== null && target === null
            ? null
            : {
                reason: String(args.reason ?? ""),
                confirm: Boolean(args.confirm),
                target_id: target,
              };
        },
      },
    },
    baselineAction: (role, request, pickAliveNotSelf, pickAliveByCamp, locale) =>
      request.allowedTools.includes("self_destruct_with_target")
        ? null
        : ORDINARY_WOLF_CONTRIBUTIONS.runtime.baselineAction!(
            role,
            request,
            pickAliveNotSelf,
            pickAliveByCamp,
            locale,
          ),
  },
  presentation: nativeRolePresentation("white_wolf_king"),
};

/**
 * Exposes White Wolf King's readonly native state and concrete consumption command.
 * Inputs are original roles or the already validated captured resource; output
 * keeps the stored reference. The window reads eligibility before commitment;
 * only the selected blast commit writes stock, without changing phase or deaths.
 * Invalid or expired windows remain their owner's terminal checks, not this port.
 */
export { getWhiteWolfKingState, consumeWhiteWolfDetonation } from "./state";

/**
 * 负责熊的原私有状态槽直接读写及普通历史追加；输入为原角色／状态／报告，安装和读取返回原引用，历史追加无返回值。
 * 状态安装先赋原槽再返回，读取只是类型断言，不执行 schema／Proxy／当前性检查或深冻结。
 * 数据契约属于共享包，名单、生命、实际吼叫判定、玩家知识和检查点编码仍归各实际所有者。
 * 普通发布取原 history.push 追加；黎明政策保留 frame 自己的受控 writer，本叶不合并两种写入。
 * 原写入或 getter／push 失败直接传播，不保存镜像、退款或授予请求权限。
 */
import type { BearState, BearReadState } from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";

/** 保留 privateState 的原 LHS 读取和同对象赋值；允许的状态形状仍由安装调用方负责。 */
export function setBearState(role: RoleComponent, state: BearState): BearReadState {
  (role.privateState as { bear: BearState })["bear"] = state;
  return state;
}

/** 返回原 live 引用；BearReadState 的 readonly 约束不代表运行时冻结或合法性验证。 */
export function getBearState(role: RoleComponent): BearReadState | undefined {
  return (role.privateState as { readonly bear?: unknown })["bear"] as BearReadState | undefined;
}

/** 普通发布先读取 history／push，再追加原报告对象；后错不回滚，黎明独立 writer 不经此命令。 */
export function recordBearRoar(state: BearReadState, report: BearState["history"][number]): void {
  (state.history as BearState["history"]).push(report);
}

/**
 * 负责 熊 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数与角色组件；输出为角色资料、配置解析、初始化和展示标识四项贡献，保留原引用与顺序。
 * 展示只登记 bear 标识，实际玩家知识投影归共同观察所有者；本模块不读取动物板知识、授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
import { nativeRolePresentation } from "../presentation-contribution";
import { z } from "zod";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { BEAR_SIGNAL_POLICIES } from "@ai-werewolf-arena/game-contract";
import { Camp, Role } from "../../../../core/domain/model";
import type { NativeRoleContributions } from "../contracts";
import { getBearState, setBearState } from "./state";
const parameters = z.strictObject({ signalPolicy: z.enum(BEAR_SIGNAL_POLICIES).optional() });

export const BEAR_ROLE_PROFILE: NativeRoleContributions = {
  metadata: {
    role: Role.Bear,
    camp: Camp.Good,
    goodSide: "god",
    maxCount: 1,
    label: roleName("bear"),
    skillBrief: text("zh-CN", "role.bear.brief"),
  },
  runtime: {
    init: (role) => {
      setBearState(role, { history: [] });
    },
    configuration: {
      schema: parameters,
      defaults: {},
      apply: (config, value) => {
        const p = parameters.parse(value);
        return p.signalPolicy ? { ...config, bear: { signalPolicy: p.signalPolicy } } : config;
      },
      serialize: (config) => parameters.parse(config.bear ?? {}),
    },
  },
  presentation: nativeRolePresentation("bear"),
};

/**
 * 提供熊状态与夜前采样／黎明发布 frame 的实际公开绑定。输入为原角色、安装数据或 World／日期／政策；
 * 输出保留原状态引用和同一 frame，不另做采样、校验、复制、冻结或存储。
 * 初始化写权与请求权限仍归原调用方；frame 在原时点校验生命、原体和发布租约，关闭／失败保原前缀。
 * 本入口只具名导出真实状态函数和 class，公开 frame 不是行动许可或 JSON 数据。
 */
export { getBearState, setBearState } from "./state";
export { BearNightFrame } from "./night_frame";

/**
 * 负责守墓人原私有状态槽的安装、同引用读取及已接受反馈的历史写入。
 * 输入是原角色／状态、当时捕获的放逐标签与接收日期；输出保留原状态引用或追加的报告副本。
 * 数据保存放逐日、目标、查验结果与接收日；公共字段类型归中立契约，本模块不新增 live schema 校验。
 * 阶段拥有资格、重复接收检查与事件发布；历史 push 的原 getter／spread／失败前缀保留，不回滚已写报告。
 * readonly 是读方类型，不冻结库存、验证原生命或授予行动许可；这里不捕获身份标签或推进阶段。
 */
import type {
  GravekeeperReport,
  GravekeeperState,
  GravekeeperReadReport,
  GravekeeperReadState,
} from "@ai-werewolf-arena/game-contract";

import type { RoleComponent } from "../../../../core/domain/components/role";
import type { ExileFeedback } from "@ai-werewolf-arena/game-contract";

/** 直接安装同一输入状态，先求原 privateState 左值；不创建／克隆、冻结或检查状态形状。 */
export function setGravekeeperState(
  roleComp: RoleComponent,
  state: GravekeeperState,
): GravekeeperReadState {
  (roleComp.privateState as { gravekeeper: GravekeeperState })["gravekeeper"] = state;
  return state;
}

/** 原直接字段读取，不校验角色／阵营／生命或 schema；调用方负责提供原组件，getter 失败照常传播。 */
export function getGravekeeperState(roleComp: RoleComponent): GravekeeperReadState | undefined {
  return (roleComp.privateState as { readonly gravekeeper?: unknown })["gravekeeper"] as
    GravekeeperReadState | undefined;
}

/** 调用方保留前置资格与后续发布；这里先取 history.push 的原 receiver，再展开 fact 和其 result 副本。
 * 不把收到的反馈当资源付款；push／spread 失败不补事件，已完成的写入不由本函数回滚。 */
export function recordExileFeedback(
  state: GravekeeperReadState,
  fact: ExileFeedback,
  receivedDay: number,
): void {
  (state.history as GravekeeperReport[]).push({ ...fact, receivedDay, result: { ...fact.result } });
}

/**
 * 负责 守墓人 的原资料、初始化与运行贡献装配，内建展示只登记语言中立的具体角色标识。
 * 输入为原板子参数、角色组件与请求上下文；输出为分别登记的资料、运行及展示贡献，工具、阶段、初始化和特权 mock 回调保留原引用与顺序。
 * 展示在实际调用时由角色捕获读取原状态并逐片段交纯展示所有者；本模块不授予租约、执行归档或复制状态。
 * 失败和关闭时仍遵守原机制权限与已付费前缀，不把文案当授权。
 */
