 */
import { recordBearRoar } from "./state";

import type { BearReadState as BearState } from "@ai-werewolf-arena/game-contract";

import { types } from "node:util";
import {
  AliveComponent,
  aliveLifeVersion,
  aliveLifeDescriptor,
} from "../../../../core/domain/components/alive";
import { COMPONENT } from "../../../../core/domain/components/names";
import type { RoleComponent } from "../../../../core/domain/components/role";
import type { IdentityComponent } from "../../../../core/domain/entities/player";
