import { RoleCatalog } from "../catalog";
import { getDefaultRoleCatalog } from "../role-catalog-assembly";
import { getBearState } from "./state";
import { BEAR_SIGNAL_POLICIES, type BearSignalPolicy } from "@ai-werewolf-arena/game-contract";
import {
  captureOriginalPlayer,
  originalPlayerSameLife,
  type OriginalPlayerScope,
} from "../original_player_scope";
import type { CampComponent } from "../../../../core/domain/components/camp";
import { snapshotPlainData } from "../../../../core/domain/plain_data";
const dawnPublications = new WeakMap<
  World,
  Map<number, { status: "checking" | "published" | "revoked" }>
>();
const now = Date.now.bind(Date);
function ownData(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return undefined;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : undefined;
}
function appendable(value: unknown): value is unknown[] {
  if (
    !Array.isArray(value) ||
    types.isProxy(value) ||
    Object.getPrototypeOf(value) !== Array.prototype
  )
    return false;
  const d = Object.getOwnPropertyDescriptor(value, "length");
  return (
    !!d?.writable &&
    Number.isSafeInteger(d.value) &&
    d.value < 4294967295 &&
    Object.isExtensible(value)
  );
}
function unpublishedHistory(value: unknown, day: number): boolean {
  try {
    const rows = snapshotPlainData(value, new Set(), 0, 65536);
    return Array.isArray(rows) && !rows.some((report) => ownData(report, "day") === day);
  } catch {
    return false;
  }
}

function sampleRoar(world: World, actorId: EntityId, catalog: RoleCatalog): boolean {
  const ring = world
      .getAliveEntityIds()
      .sort(
        (a, b) =>
          (world.getComponent(a, COMPONENT.Identity)?.seat ?? a) -
            (world.getComponent(b, COMPONENT.Identity)?.seat ?? b) || a - b,
      ),
    index = ring.indexOf(actorId),
    neighbors =
      index < 0 || ring.length < 2
        ? []
        : [
            ...new Set([
              ring[(index + ring.length - 1) % ring.length],
              ring[(index + 1) % ring.length],
            ]),
          ];
  return neighbors.some((id) => {
    const target = world.getComponent(id, COMPONENT.Role);
    return (
      target?.camp === Camp.Wolf &&
      (catalog.runtime(target.role)?.detectableByBear?.(world, target) ?? true)
    );
  });
}

/** 快照由 manager 持有，不放在玩家 component 或 DTO 中。 */
export class BearNightFrame {
  private constructor(
    private readonly owner: World,
    private readonly day: number,
    private readonly actorId: EntityId,
    private readonly role: RoleComponent,
    private readonly state: BearState,
    private readonly life: AliveComponent,
    private readonly lifeVersion: number,
    private readonly wasAlive: boolean,
    private readonly sampledRoar: boolean,
    private readonly signalPolicy: BearSignalPolicy,
    private readonly catalog: RoleCatalog,
    private readonly originals: readonly OriginalPlayerScope[],
    private readonly camp: CampComponent | undefined,
  ) {}

  static capture(
    world: World,
    day: number,
    catalog: RoleCatalog = getDefaultRoleCatalog(),
    signalPolicy: BearSignalPolicy = "awa_night_open_v1",
  ): BearNightFrame | null {
    if (!BEAR_SIGNAL_POLICIES.includes(signalPolicy)) throw Error("bear_signal_policy_invalid");
    const bears = world
      .entityIds()
      .filter((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.Bear);
    if (bears.length > 1) throw new Error("bear_count_exceeds_limit");
    const actorId = bears[0];
    if (actorId === undefined) return null;
    const role = world.getComponent(actorId, COMPONENT.Role)!,
      state = getBearState(role),
      life = world.getComponent(actorId, COMPONENT.Alive),
      version = life && aliveLifeVersion(life);
    if (role.camp !== Camp.Good || !state || !life || version === undefined) return null;
    const originals =
        signalPolicy === "netease_dawn_live_v1"
          ? world.getAliveEntityIds().map((id) => captureOriginalPlayer(world, id))
          : [],
      camp = world.getComponent(actorId, COMPONENT.Camp);
    if (
      originals.some((p) => p === null) ||
      (signalPolicy === "netease_dawn_live_v1" && camp?.camp !== Camp.Good)
    )
      return null;
    const roared =
      signalPolicy === "awa_night_open_v1" ? sampleRoar(world, actorId, catalog) : false;
    return new BearNightFrame(
      world,
      day,
      actorId,
      role,
      state,
      life,
      version,
      life.alive,
      roared,
      signalPolicy,
      catalog,
      originals as OriginalPlayerScope[],
      camp,
    );
  }

  /** 完整夜死亡波后、该波判胜前发表。 */
  publish(world: World, events: GameEvent[], isCurrent: () => boolean): void {
    if (this.signalPolicy === "netease_dawn_live_v1") {
      this.publishDawn(world, events, isCurrent);
      return;
    }
    if (
      world !== this.owner ||
      !isCurrent() ||
      world.getComponent(this.actorId, COMPONENT.Role) !== this.role ||
      this.role.role !== Role.Bear ||
      this.role.camp !== Camp.Good ||
      getBearState(this.role) !== this.state ||
      world.getComponent(this.actorId, COMPONENT.Alive) !== this.life ||
      aliveLifeVersion(this.life) !==
        this.lifeVersion + (this.wasAlive && !this.life.alive ? 1 : 0) ||
      this.state.history.some((report) => report.day === this.day)
    )
      return;
    const report = { day: this.day, roared: this.life.alive && this.wasAlive && this.sampledRoar };
    recordBearRoar(this.state, report);
    events.push({ timestamp: Date.now(), type: "bear_roared", payload: { ...report } });
  }
  private dawnBodyCurrent(world: World): boolean {
    const factory = aliveLifeDescriptor(this.life);
    if (!factory) return false;
    const actual = Object.getOwnPropertyDescriptor(this.life, "alive"),
      history = ownData(this.state, "history");
    return (
      actual?.get === factory.get &&
      actual?.set === factory.set &&
      world.getComponent(this.actorId, COMPONENT.Role) === this.role &&
      ownData(this.role, "role") === Role.Bear &&
      ownData(this.role, "camp") === Camp.Good &&
      ownData(ownData(this.role, "privateState"), "bear") === this.state &&
      world.getComponent(this.actorId, COMPONENT.Alive) === this.life &&
      aliveLifeVersion(this.life) ===
        this.lifeVersion + (this.wasAlive && !this.life.alive ? 1 : 0) &&
      world.getComponent(this.actorId, COMPONENT.Camp) === this.camp &&
      ownData(this.camp, "camp") === Camp.Good &&
      this.originals.every((p) => originalPlayerSameLife(world, p, true)) &&
      world.getAliveEntityIds().every((id) => this.originals.some((p) => p.id === id)) &&
      unpublishedHistory(history, this.day)
    );
  }
  private publishDawn(world: World, events: GameEvent[], isCurrent: () => boolean): void {
    if (world !== this.owner) return;
    let publications = dawnPublications.get(world);
    if (!publications) {
      publications = new Map();
      dawnPublications.set(world, publications);
    }
    const prior = publications.get(this.day);
    if (prior) {
      if (prior.status === "checking") prior.status = "revoked";
      return;
    }
    const lease: { status: "checking" | "published" | "revoked" } = { status: "checking" };
    publications.set(this.day, lease);
    try {
      if (!isCurrent() || !this.dawnBodyCurrent(world)) return;
      const before = this.originals.map((p) => ({
          p,
          version: aliveLifeVersion(p.life),
          identity: world.getComponent(p.id, COMPONENT.Identity),
          seat: ownData(world.getComponent(p.id, COMPONENT.Identity), "seat"),
        })),
        sampled =
          this.life.alive && this.wasAlive ? sampleRoar(world, this.actorId, this.catalog) : false;
      if (
        !isCurrent() ||
        lease.status !== "checking" ||
        !this.dawnBodyCurrent(world) ||
        before.some(
          ({ p, version, identity, seat }) =>
            aliveLifeVersion(p.life) !== version ||
            world.getComponent(p.id, COMPONENT.Identity) !== identity ||
            ownData(identity, "seat") !== seat,
        )
      )
        return;
      const history = ownData(this.state, "history");
      if (history === events || !appendable(history) || !appendable(events)) return;
      const report = { day: this.day, roared: this.life.alive && this.wasAlive && sampled },
        event: GameEvent = { timestamp: now(), type: "bear_roared", payload: { ...report } };
      // 两个 inert 数组均可追加，两次写入间不执行用户回调／setter。
      Object.defineProperty(events, String(events.length), {
        value: event,
        enumerable: true,
        writable: true,
        configurable: true,
      });
      Object.defineProperty(history, String(history.length), {
        value: report,
        enumerable: true,
        writable: true,
        configurable: true,
      });
      lease.status = "published";
    } finally {
      if (lease.status === "checking") lease.status = "revoked";
    }
  }
}

/**
 * 负责将角色／能力状态裁剪为已授权玩家可见 DTO；公共结构归 game-contract 的玩家视图契约。
 * 输入为现有状态读视图或显式事实字段；输出为独立投影，不泄露内部来源身份、库存写权或授权句柄。
 * 赠枪投影同时供原 transfer 制作安装数据，字段／status 求值顺序保持；本模块不授枪或转移资源。
 * 纯字段校验和复制只作用于数据，不读 World、时钟、RNG、文件或模型服务。
 */
import type { DeathGunReadView } from "@ai-werewolf-arena/game-contract";
import type {
  PlayerGuardState,
  PlayerHunterState,
  PlayerWolfKingState,
  PlayerWhiteWolfKingState,
  PlayerKnightState,
  PlayerIdiotState,
  PlayerDreamerState,
  PlayerWolfBeautyState,
  PlayerBearState,
  PlayerSeerState,
  PlayerWitchState,
  PlayerRoleInspectionState,
  PlayerDeathGun,
} from "@ai-werewolf-arena/game-contract/player-state-views";
import { WitchSelfHealRule } from "../../../core/domain/model";
import { readInspectionResult } from "@ai-werewolf-arena/replay-contract";

/** 只读取声明的自身数据属性，不调用该字段访问器；不承诺对任意 Proxy 零反射 trap。 */
export function playerDataField(value: unknown, key: string): unknown {
  if (!value || typeof value !== "object" || Array.isArray(value)) return undefined;
  const field = Object.getOwnPropertyDescriptor(value, key);
  return field && Object.hasOwn(field, "value") ? field.value : undefined;
}
function positiveInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}
function positiveOrNull(value: unknown): number | null {
  return positiveInteger(value) ? value : null;
}
function stock(value: unknown): number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0 ? value : 0;
}
function rows(value: unknown): unknown[] {
  if (!Array.isArray(value)) return [];
  const result: unknown[] = [];
  for (let index = 0; index < value.length; index++) {
    const field = Object.getOwnPropertyDescriptor(value, String(index));
    if (field && Object.hasOwn(field, "value")) result.push(field.value);
  }
  return result;
}
function nullableTarget(value: unknown): value is number | null {
  return value === null || positiveInteger(value);
}
function inspection(value: unknown) {
  const kind = playerDataField(value, "kind");
  return readInspectionResult(
    kind === "camp"
      ? { kind, camp: playerDataField(value, "camp") }
      : kind === "role"
        ? { kind, role: playerDataField(value, "role") }
        : kind === "combined"
          ? { kind, camp: playerDataField(value, "camp"), role: playerDataField(value, "role") }
          : null,
  );
}

export function projectGuardState(state: unknown): PlayerGuardState {
  const policy = playerDataField(state, "repeatPolicy");
  return {
    lastTarget: positiveOrNull(playerDataField(state, "lastTarget")),
    ...(policy === "awa_last_action_v1" || policy === "netease_consecutive_nights_v1"
      ? { repeatPolicy: policy }
      : {}),
  };
}
function projectGunState(state: unknown): PlayerHunterState {
  const policy = playerDataField(state, "deathActionPolicy");
  return {
    canShoot: playerDataField(state, "canShoot") === true,
    ...(policy === "awa_qualified_sources_v1" || policy === "awa_knife_or_exile_v1"
      ? { deathActionPolicy: policy }
      : {}),
  };
}
export function projectHunterState(state: unknown): PlayerHunterState {
  return projectGunState(state);
}
export function projectWolfKingState(state: unknown): PlayerWolfKingState {
  return {
    ...projectGunState(state),
    ...(playerDataField(state, "deathActionPolicy") === "awa_day_deaths_v1"
      ? { deathActionPolicy: "awa_day_deaths_v1" as const }
      : {}),
  };
}
export function projectWhiteWolfKingState(state: unknown): PlayerWhiteWolfKingState {
  return { canDetonate: playerDataField(state, "canDetonate") === true };
}
export function projectKnightState(state: unknown): PlayerKnightState {
  return { canDuel: playerDataField(state, "canDuel") === true };
}
export function projectIdiotState(state: unknown): PlayerIdiotState {
  return { revealed: playerDataField(state, "revealed") === true };
}
export function projectDreamerState(state: unknown): PlayerDreamerState {
  const policy = playerDataField(state, "protectionPolicy");
  return {
    ...(policy === "awa_night_damage_v1" || policy === "netease_2026_night_immunity_v1"
      ? { protectionPolicy: policy }
      : {}),
    lastTarget: positiveOrNull(playerDataField(state, "lastTarget")),
    lastDay: positiveOrNull(playerDataField(state, "lastDay")),
    history: rows(playerDataField(state, "history")).flatMap((row) => {
      const day = playerDataField(row, "day"),
        targetId = playerDataField(row, "targetId");
      return positiveInteger(day) && positiveInteger(targetId) ? [{ day, targetId }] : [];
    }),
  };
}
export function projectWolfBeautyState(state: unknown): PlayerWolfBeautyState {
  const policy = playerDataField(state, "deathLinkPolicy");
  return {
    ...(policy === "awa_exile_poison_v1" || policy === "heroes_s7_2017_exile_hunter_v1"
      ? { deathLinkPolicy: policy }
      : {}),
    targetId: positiveOrNull(playerDataField(state, "targetId")),
    lastActedDay: positiveOrNull(playerDataField(state, "lastActedDay")),
    history: rows(playerDataField(state, "history")).flatMap((row) => {
      const day = playerDataField(row, "day"),
        targetId = playerDataField(row, "targetId");
      return positiveInteger(day) && nullableTarget(targetId) ? [{ day, targetId }] : [];
    }),
  };
}
export function projectBearState(state: unknown): PlayerBearState {
  return {
    history: rows(playerDataField(state, "history")).flatMap((row) => {
      const day = playerDataField(row, "day"),
        roared = playerDataField(row, "roared");
      return positiveInteger(day) && typeof roared === "boolean" ? [{ day, roared }] : [];
    }),
  };
}
export function projectSeerState(state: unknown): PlayerSeerState {
  const targetPolicy = playerDataField(state, "targetPolicy"),
    actionPolicy = playerDataField(state, "actionPolicy");
  const lastIsWerewolf = playerDataField(state, "lastIsWerewolf"),
    lastResult = playerDataField(state, "lastResult");
  return {
    ...(targetPolicy === "awa_alive_v1" || targetPolicy === "awa_fresh_others_v1"
      ? { targetPolicy }
      : {}),
    ...(actionPolicy === "awa_optional_v1" || actionPolicy === "awa_required_when_legal_v1"
      ? { actionPolicy }
      : {}),
    lastTarget: positiveOrNull(playerDataField(state, "lastTarget")),
    lastIsWerewolf: typeof lastIsWerewolf === "boolean" ? lastIsWerewolf : null,
    ...(lastResult === undefined
      ? {}
      : { lastResult: lastResult === null ? null : inspection(lastResult) }),
    history: rows(playerDataField(state, "history")).flatMap((row) => {
      const targetId = playerDataField(row, "targetId"),
        isWerewolf = playerDataField(row, "isWerewolf"),
        result = inspection(playerDataField(row, "result"));
      return positiveInteger(targetId) && typeof isWerewolf === "boolean"
        ? [{ targetId, isWerewolf, ...(result ? { result } : {}) }]
        : [];
    }),
  };
}
export function projectWitchState(state: unknown): PlayerWitchState {
  const rule = playerDataField(state, "selfHealRule");
  const knifeVisibility = playerDataField(state, "knifeVisibility"),
    potionPolicy = playerDataField(state, "potionPolicy");
  return {
    ...(knifeVisibility === "awa_with_heal_v1" || knifeVisibility === "awa_always_v1"
      ? { knifeVisibility }
      : {}),
    ...(potionPolicy === "awa_one_native_v1" || potionPolicy === "awa_both_native_experimental_v1"
      ? { potionPolicy }
      : {}),
    heal: stock(playerDataField(state, "heal")),
    poison: stock(playerDataField(state, "poison")),
    selfHealRule:
      rule === WitchSelfHealRule.Always || rule === WitchSelfHealRule.FirstNightOnly
        ? rule
        : WitchSelfHealRule.Disabled,
    canSelfHeal: playerDataField(state, "canSelfHeal") === true,
    healUsedThisNight: playerDataField(state, "healUsedThisNight") === true,
    poisonUsedThisNight: playerDataField(state, "poisonUsedThisNight") === true,
  };
}
export function projectRoleInspectionState(state: unknown): PlayerRoleInspectionState {
  const policy = playerDataField(state, "policy"),
    inspectionPolicy = playerDataField(state, "inspectionPolicy");
  return {
    ...(inspectionPolicy === "awa_unique_required_v1" ||
    inspectionPolicy === "awa_repeat_optional_v1" ||
    inspectionPolicy === "awa_unique_optional_v1"
      ? { inspectionPolicy }
      : {}),
    ...(policy === "gargoyle" ||
    policy === "psychic" ||
    policy === "mirror" ||
    policy === "pure_white" ||
    policy === "wolf_witch"
      ? { policy }
      : {}),
    lastTarget: positiveOrNull(playerDataField(state, "lastTarget")),
    lastDay: positiveOrNull(playerDataField(state, "lastDay")),
    history: rows(playerDataField(state, "history")).flatMap((row) => {
      const day = playerDataField(row, "day"),
        targetId = playerDataField(row, "targetId"),
        result = inspection(playerDataField(row, "result"));
      return positiveInteger(day) && positiveInteger(targetId) && result?.kind === "role"
        ? [{ day, targetId, result }]
        : [];
    }),
  };
}

export function projectDeathGun(gun: DeathGunReadView): PlayerDeathGun {
  return {
    id: gun.id,
    kind: "gun",
    source: { kind: gun.source.kind },
    sourceDisclosed: false,
    grantedNight: gun.grantedNight,
    armedOnNight: gun.armedOnNight,
    remaining: gun.remaining,
    disabled: gun.disabled,
    deathExpired: gun.deathExpired,
    status:
      gun.disabled || gun.deathExpired
        ? "disabled"
        : gun.remaining === 0
          ? "spent"
          : gun.armedOnNight === null
            ? "pending"
            : "active",
  };
}

/**
 * 负责完整捕获玩家可获知的身份、机制知识、已发表死亡、行动历史与能力／枪信息。
 * 输入为原请求与按原时点执行的窄查询；输出是原字段集合的脱离冻结 PlayerObservation。
 * World 仅在此游戏侧 adapter 读取，不交给策略；已知存活依发布事实计算，不替换为真实存活名单。
 * 角色和队友方法在 actor 参数之前查找；每个 World 读取保原位置，机制知识／权限仍归各原 owner。
 * 结构观察不提交行动、不克隆完整私有库存，也不提前执行自定义人设或角色展示回调；失败前缀保持。
 */
import { getWhiteWolfKingState } from "../mechanisms/roles/white_wolf_king/ports";
import { isAnimalDreamBoard } from "../mechanisms/roles/animal_dream/authority";
import {
  animalFoxKnowledge,
  animalPufferKnowledge,
  animalCatKnowledge,
